import math

def binary_search(array, value):
  low = 0
  high = length(array) - 1

  while(low <= high):
    mid = math.ceil((low + high)/2)
    guess = array[mid]
    if guess == value:
      return mid
    if guess > value:
      high = mid - 1
    else:
      low = mid + 1

  return None

