def bus(k, arr, last):
    s = 0
    r = 0
    m = 0
    if last - arr[-1] > k:
        return 0
    else:
        for i in range(len(arr) - 1):
            if arr[i] - s <= k:
                r += (arr[i] - s)
                if r == k:
                    m += 1
                    r = 0
                else:
                    if r + arr[i + 1] - arr[i] > k:
                        m += 1
                        r = 0
                s = arr[i]
            else:
                return 0
        if arr[-1] - s <= k:
            r += arr[-1] - s
            if r == k:
                m += 1
                r = 0
                return m
            else:
                if r + last - arr[-1] > k:
                    m += 1
                    r = 0
                return m
        else:
            return 0

